s\n\nCo-Authored-By: Claude <noreply@anthropic.com>","tree":{"sha":"cc2762a6d23ae34d274ef7a8af5590e2c081510c","url":"https://api.github.com/repos/davidarce/DevRune/git/trees/cc2762a6d23ae34d274ef7a8af5590e2c081510c"},"url":"https://api.github.com/repos/davidarce/DevRune/git/commits/2e92f87246ef1a10746452211f8198a73abd2556","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/13999850?v=4","events_url":"https://api.github.com/users/davidarce/events{/privacy}","followers_url":"https://api.github.com/users/davidarce/followers","following_url":"https://api.github.com/users/davidarce/following{/other_user}","gists_url":"https://api.github.com/users/davidarce/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/davidarce","id":13999850,"login":"davidarce","node_id":"MDQ6VXNlcjEzOTk5ODUw","organizations_url":"https://api.github.com/users/davidarce/orgs","received_events_url":"https://api.github.com/users/davidarce/received_events","repos_url":"https://api.github.com/users/davidarce/repos","site_admin":false,"starred_url":"https://api.github.com/users/davidarce/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/davidarce/subscriptions","type":"User","url":"https://api.github.com/users/davidarce","user_view_type":"public"},"html_url":"https://github.com/davidarce/DevRune/commit/2e92f87246ef1a10746452211f8198a73abd2556","node_id":"C_kwDORt3vE9oAKDJlOTJmODcyNDZlZjFhMTA3NDY0NTIyMTFmODE5OGE3M2FiZDI1NTY","parents":[{"html_url":"https://github.com/davidarce/DevRune/commit/b00e9d1e53608f1631744f121fffbc82e91e46bd","sha":"b00e9d1e53608f1631744f121fffbc82e91e46bd","url":"https://api.github.com/repos/davidarce/DevRune/commits/b00e9d1e53608f1631744f121fffbc82e91e46bd"}],"sha":"2e92f87246ef1a10746452211f8198a73abd2556","url":"https://api.github.com/repos/davidarce/DevRune/commits/2e92f87246ef1a10746452211f8198a73abd2556"},{"author":{"