INSERT INTO collection_pages VALUES('3677bab7afd82c5b075f708a3ffcfb01beefc270e4497a453f4b6bc17c003722','f2190a38092bb1bed9223dfcb77e0c16c194c5fad01b82b913d0acf0eb8c2cb3','{"hasNext":false,"items":[{"author":{"account":null,"email":"andrius.ziobakas@bewatec.com","name":"Andrius Ziobakas"},"authoredDate":"2026-03-23T15:11:10Z","committedDate":"2026-03-23T15:11:10Z","committer":{"account":null,"email":"andrius.ziobakas@bewatec.com","name":"Andrius Ziobakas"},"observedAt":"2026-10-08T22:19:16.383Z","repositoryId":1189639453,"sha":"6ed0fdc60070b168b0fd5fe54c693ab343fa0a3a"},{"author":{"account":null,"email":"andrius.ziobakas@bewatec.com","name":"Andrius Ziobakas"},"authoredDate":"2026-03-23T14:19:59Z","committedDate":"2026-03-23T14:19:59Z","committer":{"account":null,"email":"andrius.ziobakas@bewatec.com","name":"Andrius Ziobakas"},"observedAt":"2026-10-08T22:19:16.383Z","repositoryId":1189639453,"sha":"d621ac6df3efe04a2d4e7309610a23366162bf3d"}],"observedAt":"2026-10-08T22:19:16.383Z","raw":[{"author":null,"comments_url":"https://api.github.com/repos/aziobakas/oidc-spa-mfe-repro/commits/6ed0fdc60070b168b0fd5fe54c693ab343fa0a3a/comments","commit":{"author":{"date":"2026-03-23T15:11:10Z","email":"andrius.ziobakas@bewatec.com","name":"Andrius Ziobakas"},"comment_count":0,"committer":{"date":"2026-03-23T15:11:10Z","email":"andrius.ziobakas@bewatec.com","name":"Andrius Ziobakas"},"message":"Document two-client-ID requirement for workaround\n\nThe workaround (callback routing, listener ordering, lazy init) only\nworks when each remote uses a different Keycloak client ID. With a\nsingle client ID, stopImmediatePropagation in earlyInit.ts blocks ALL\noidc-spa iframe messages unconditionally.\n\nUpdate README with broken vs workaround toggle instructions, detailed\nexplanation of what fails and why, and the client ID requirement.\n\nRestore workaround bootstrap to match production admin-ui pattern with\ngetCallbackOwner, hideFragment, and restoreFragment helpers.","tree":{"sha":