ine\ncontent SVG in text.","tree":{"sha":"9812e125eacdf31137b02e08de07e629c333d5e5","url":"https://api.github.com/repos/FJCF76/PromptingPress/git/trees/9812e125eacdf31137b02e08de07e629c333d5e5"},"url":"https://api.github.com/repos/FJCF76/PromptingPress/git/commits/cfb6103a6650d84dd348d0136b46f236847389c4","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/79067086?v=4","events_url":"https://api.github.com/users/FJCF76/events{/privacy}","followers_url":"https://api.github.com/users/FJCF76/followers","following_url":"https://api.github.com/users/FJCF76/following{/other_user}","gists_url":"https://api.github.com/users/FJCF76/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/FJCF76","id":79067086,"login":"FJCF76","node_id":"MDQ6VXNlcjc5MDY3MDg2","organizations_url":"https://api.github.com/users/FJCF76/orgs","received_events_url":"https://api.github.com/users/FJCF76/received_events","repos_url":"https://api.github.com/users/FJCF76/repos","site_admin":false,"starred_url":"https://api.github.com/users/FJCF76/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/FJCF76/subscriptions","type":"User","url":"https://api.github.com/users/FJCF76","user_view_type":"public"},"html_url":"https://github.com/FJCF76/PromptingPress/commit/cfb6103a6650d84dd348d0136b46f236847389c4","node_id":"C_kwDORu3kjNoAKGNmYjYxMDNhNjY1MGQ4NGRkMzQ4ZDAxMzZiNDZmMjM2ODQ3Mzg5YzQ","parents":[{"html_url":"https://github.com/FJCF76/PromptingPress/commit/8568fb4aa4be0ba262f4319ec19c0044b6a41fb9","sha":"8568fb4aa4be0ba262f4319ec19c0044b6a41fb9","url":"https://api.github.com/repos/FJCF76/PromptingPress/commits/8568fb4aa4be0ba262f4319ec19c0044b6a41fb9"}],"sha":"cfb6103a6650d84dd348d0136b46f236847389c4","url":"https://api.github.com/repos/FJCF76/PromptingPress/commits/cfb6103a6650d84dd348d0136b46f236847389c4"},{"author":{"avatar_url":"https://avatars.githubuse