er ruling Q1.","tree":{"sha":"a1a24c9c8cbd0cb9b290241bd1b6880d4fe35c43","url":"https://api.github.com/repos/FJCF76/PromptingPress/git/trees/a1a24c9c8cbd0cb9b290241bd1b6880d4fe35c43"},"url":"https://api.github.com/repos/FJCF76/PromptingPress/git/commits/0dea0bacd03b0b1d226ae0fa128124410e133fb4","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/79067086?v=4","events_url":"https://api.github.com/users/FJCF76/events{/privacy}","followers_url":"https://api.github.com/users/FJCF76/followers","following_url":"https://api.github.com/users/FJCF76/following{/other_user}","gists_url":"https://api.github.com/users/FJCF76/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/FJCF76","id":79067086,"login":"FJCF76","node_id":"MDQ6VXNlcjc5MDY3MDg2","organizations_url":"https://api.github.com/users/FJCF76/orgs","received_events_url":"https://api.github.com/users/FJCF76/received_events","repos_url":"https://api.github.com/users/FJCF76/repos","site_admin":false,"starred_url":"https://api.github.com/users/FJCF76/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/FJCF76/subscriptions","type":"User","url":"https://api.github.com/users/FJCF76","user_view_type":"public"},"html_url":"https://github.com/FJCF76/PromptingPress/commit/0dea0bacd03b0b1d226ae0fa128124410e133fb4","node_id":"C_kwDORu3kjNoAKDBkZWEwYmFjZDAzYjBiMWQyMjZhZTBmYTEyODEyNDQxMGUxMzNmYjQ","parents":[{"html_url":"https://github.com/FJCF76/PromptingPress/commit/8568fb4aa4be0ba262f4319ec19c0044b6a41fb9","sha":"8568fb4aa4be0ba262f4319ec19c0044b6a41fb9","url":"https://api.github.com/repos/FJCF76/PromptingPress/commits/8568fb4aa4be0ba262f4319ec19c0044b6a41fb9"}],"sha":"0dea0bacd03b0b1d226ae0fa128124410e133fb4","url":"https://api.github.com/repos/FJCF76/PromptingPress/commits/0dea0bacd03b0b1d226ae0fa128124410e133fb4"},{"author":{"avatar_url":"https://avatars.githubusercontent.com